from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN, ROUND_HALF_UP
from typing import List, Union

from pydantic import BaseModel, conint, validator, ValidationError


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: Decimal

    @validator("unit_price", pre=True)
    def validate_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal, must be >= 0
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places exactly, rounding half up
        return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API with:
    - number (str)
    - issued_at formatted as YYYY-MM-DDTHH:MM:SSZ in UTC
    - lines: list of {sku, quantity, unit_price} with unit_price as string with 2 decimals
    - total: string with 2 decimals (sum of quantity * unit_price)
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ (UTC)
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with exactly two decimals
    lines_out = []
    total = Decimal("0.00")
    for line in invoice.lines:
        line_total = line.unit_price * line.quantity
        total += line_total
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": f"{line.unit_price:.2f}",
            }
        )

    total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

    import json

    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }
    return json.dumps(out, separators=(",", ":"))

from typing import List, Optional

from pydantic import BaseModel, validator


class ImportProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def clean_display_name(cls, value: str) -> str:
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def zip_code_to_str(cls, value) -> str:
        # Accept int or str, store as str
        return str(value)


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = ImportProfile.parse_obj(row)
            # Return dict with only required keys in the requested order
            valid_profiles.append(
                {
                    "user_id": profile.user_id,
                    "display_name": profile.display_name,
                    "bio": profile.bio,
                    "zip_code": profile.zip_code,
                }
            )
        except Exception:
            # Silently skip invalid rows
            pass
    return valid_profiles

from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from typing import List, Union

from pydantic import BaseModel, Field, field_validator, ValidationError


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_validator("unit_price", mode="before")
    @classmethod
    def coerce_unit_price(cls, v) -> Decimal:
        # Accept str/int/float, convert to Decimal
        try:
            d = Decimal(str(v))
        except (InvalidOperation, ValueError):
            raise ValueError("unit_price must be a decimal number >= 0")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d

    def unit_price_str(self) -> str:
        # Format unit_price as string with exactly two decimals
        return f"{self.unit_price:.2f}"


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[InvoiceLine]

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v) -> datetime:
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except ValueError:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")

        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    def issued_at_str(self) -> str:
        # Format as "YYYY-MM-DDTHH:MM:SSZ" in UTC
        dt_utc = self.issued_at
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

    def total(self) -> Decimal:
        total = Decimal("0")
        for line in self.lines:
            total += line.unit_price * line.quantity
        return total


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # Raise ValueError as requested
        raise ValueError(e.errors())

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": invoice.issued_at_str(),
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": line.unit_price_str(),
            }
            for line in invoice.lines
        ],
        "total": f"{invoice.total():.2f}",
    }

    import json

    return json.dumps(out, separators=(",", ":"))

import re
from pydantic import BaseModel, field_validator, ValidationError


class SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @field_validator("username")
    @classmethod
    def validate_username(cls, v: str) -> str:
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @field_validator("phone")
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r"[ \.\-\(\)]", "", v)
        if not re.fullmatch(r"\+[0-9]{8,15}", compact):
            raise ValueError("phone must be '+' followed by 8-15 digits")
        return compact

    @field_validator("password")
    @classmethod
    def validate_password(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @field_validator("password_confirm")
    @classmethod
    def validate_password_confirm(cls, v: str, info) -> str:
        # We cannot validate equality here because password_confirm is validated before password
        # So validate equality in root_validator instead
        return v

    @classmethod
    def model_validate(cls, data):
        # Use BaseModel's model_validate to get ValidationError on field validators
        obj = super().model_validate(data)
        # Check password == password_confirm
        if obj.password != obj.password_confirm:
            raise ValidationError(
                [
                    {
                        "loc": ("password_confirm",),
                        "msg": "password_confirm must equal password",
                        "type": "value_error",
                    }
                ],
                cls,
            )
        return obj


def validate_signup(data: dict) -> dict:
    validated = SignupModel.model_validate(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }
